"        if (posSettings.qrMode === 'static') {
          const activeEntry = (posSettings.staticUpiList || []).find(e => e.id === posSettings.activeStaticUpiId);
          if (activeEntry) {
            upiUri = `upi://pay?pa=${activeEntry.upiId}&pn=${encodeURIComponent(payeeName)}&cu=INR`;
            displayUpiId = activeEntry.upiId;
            const brandNames = { paytm: 'Paytm', phonepe: 'PhonePe', gpay: 'Google Pay', bhim: 'BHIM', amazonpay: 'Amazon Pay', other: '' };
            brandLabel = activeEntry.name || brandNames[activeEntry.brand] || '';
          }
        } else {
          if (posSettings.upiId) {
            let upiAmount = 0;
            if (isBookingReceipt) {
              upiAmount = parseFloat(advancePaid);
            } else if (isSettlement) {
              upiAmount = parseFloat(remainingBalance);
            } else {
              upiAmount = parseFloat(order.total_price || 0);
            }
            upiUri = `upi://pay?pa=${posSettings.upiId}&pn=${encodeURIComponent(payeeName)}&am=${upiAmount.toFixed(2)}&cu=INR`;
            displayUpiId = posSettings.upiId;
          }
        }"
